insert into public.products (id, name, material, description, long_description, price, discount_price, category, tags, sizes, stock, dimensions, accent, image, gallery, gallery_labels, colors, features, seo_title, seo_description, created_at, updated_at) values
  ('p01', 'The Kinetic Sculpt Chair', 'Black Steel + Solid Sheesham Wood', 'Premium minimalist steel frame pairing a comfortable sleek profile with handcrafted wooden arm accents.', NULL, 52000, NULL, 'Seating', '["bestseller","steel","handcrafted"]'::jsonb, '["Standard"]'::jsonb, 14, '{"h":85,"w":68,"d":68}'::jsonb, 'from-amber-50 to-stone-100', '/1.jpg.jpeg', '["/1.jpg.jpeg","/4ac55af25c7beafb9c5d653e99e778e3.jpg.jpeg"]'::jsonb, '["Front View","Side — Steel Frame & Armrests"]'::jsonb, '[{"name":"Matte Black + Sheesham","hex":"#8B5E3C","gallery":["/1.jpg.jpeg","/4ac55af25c7beafb9c5d653e99e778e3.jpg.jpeg"]}]'::jsonb, '["Heavy-gauge steel frame powder-coated matte black — will not rust or chip","Solid sheesham wood arm accents — each treated for long-term durability","Comfortable backrest angle — made for long sits, not just looks","Compact footprint — fits any room without taking too much space"]'::jsonb, 'The Kinetic Sculpt Chair — Alloyed Living', 'Premium minimalist steel and sheesham wood accent chair, handcrafted for the modern home.', '2026-01-12T09:00:00.000Z', '2026-05-02T11:20:00.000Z'),
  ('p02', 'Modern Dual-Tone Side & Nesting Tables', 'Black Steel + Tempered Glass + Walnut', 'Sophisticated, multi-layered nesting tables combining sleek geometric black steel bases with warm textured wood tops.', NULL, 38500, 34900, 'Tables', '["nesting","space-saving","glass"]'::jsonb, '["Set of 2","Set of 3"]'::jsonb, 22, '{"h":45,"w":120,"d":65}'::jsonb, 'from-stone-100 to-amber-50', '/2.jpg.jpeg', '["/2.jpg.jpeg","/3.jpg.jpeg"]'::jsonb, '["Front — Table Set View","Side — Frame & Shelf Detail"]'::jsonb, NULL, '["Multi-layered nesting design — saves space, perfect for small rooms","Geometric black steel base — sharp lines that match modern home styles","Warm textured wood top surface — easy to clean and scratch-resistant","Low-profile height — pairs well with any sofa or sectional"]'::jsonb, 'Modern Dual-Tone Nesting Tables — Alloyed Living', 'Space-saving nesting side tables with black steel bases and warm walnut tops.', '2026-01-18T09:00:00.000Z', '2026-04-28T14:05:00.000Z'),
  ('p11', 'CamScanner Catalog Items', 'Black Steel + Solid Wood', 'Premium steel and wood space-saving home decor accents to complete the modern room layout.', NULL, 45000, NULL, 'Home Decor', '["decor","accent"]'::jsonb, '["Standard"]'::jsonb, 31, '{"h":90,"w":120,"d":45}'::jsonb, 'from-stone-50 to-stone-200', '/4.jpg.jpeg', '["/4.jpg.jpeg","/9.jpg.jpeg","/10.jpg.jpeg","/11.jpg.jpeg"]'::jsonb, '["Item 1","Item 2","Item 3","Item 4"]'::jsonb, NULL, '["Premium steel and wood construction — built to last for years","Space-saving design — fits comfortably in any modern home","Multiple pieces available — complete your room in one order","Simple to set up — no special tools needed"]'::jsonb, 'Steel & Wood Home Decor Accents — Alloyed Living', 'Premium steel and solid wood decor accents for the modern home.', '2026-02-14T09:00:00.000Z', '2026-04-30T16:15:00.000Z'),
  ('p12', 'Medicated Chair', 'Black Steel + Cow Leather', 'The Medicated Chair blends therapeutic ergonomic support with a bold industrial-modern aesthetic, featuring a heavy-duty black steel frame accented by rich, solid Sheesham wood. Upholstered in premium, durable cow leather, this high-end seating solution delivers targeted posture relief and exceptional comfort for any professional workspace or home study.', NULL, 25000, 0, 'Seating', '["handcrfted"]'::jsonb, '["Medium"]'::jsonb, 19, '{"h":35,"w":21,"d":9}'::jsonb, 'from-stone-50 to-stone-200', 'https://i.pinimg.com/control1/1200x/ee/bc/73/eebc7308f01482defc3253ddef9ed834.jpg', '["https://i.pinimg.com/control1/736x/8f/f6/58/8ff65850e387f974166a0f866553fb7a.jpg","https://i.pinimg.com/1200x/56/07/3b/56073bf3c1bd5ac28392cfd9e22bb19f.jpg"]'::jsonb, NULL, NULL, NULL, NULL, 'Product Overview
insert into public.content_pages (slug, title, fields, updated_at) values
  ('home', 'Home Page', '{"hero":{"mediaType":"image","videoUrl":"/uploads/1783263465180-woman-touching-table-and-shelf-202607051941.mp4","imageUrl":"/uploads/1783263906125-hero.jpg","eyebrow":"Pakistan''s Leading Luxury Furniture Brand","titleLine1":"REDEFINING","titleLine2":"TRADITION","tagline":"Where bold design meets fine craftsmanship.","ctaLabel":"Explore Collection"},"story":{"eyebrow":"Our Story","title":"Alloyed Living brings bold design together with skilled craftsmanship.","body":"Handcrafted brass meets premium solid walnut. Every detail thoughtfully made — furniture built not just for rooms, but for a life well lived.","ctaLabel":"Our Story"},"shopRoom":{"eyebrow":"Browse the Room","title":"Shop the Room","subtitle":"Carefully chosen pieces — each one crafted to bring style and purpose to your home.","backgroundImage":"/8.jpg.jpeg","ctaLabel":"View Full Collection"},"featured":{"eyebrow":"The Collection","title":"Featured Pieces","ctaLabel":"View Full Collection","productIds":["p01","p03","p11","p02"]}}'::jsonb, '2026-07-05T15:05:13.352Z'),
  ('shop', 'Shop Page', '{"eyebrow":"The Collection","title":"Our Collection"}'::jsonb, '2026-07-04T06:23:28.238Z'),
  ('shipping', 'Shipping & Delivery', '{"heroTitle":"Delivered with Precision","heroSubtitle":"Every piece shipped with the same care taken to craft it.","freeShippingThreshold":100000,"tiers":[{"label":"Standard","window":"5 – 7 Business Days","rate":"PKR 500","freeMsg":"Free over PKR 100,000","carrier":"TCS · Leopard Courier","note":"Reliable nationwide delivery with SMS tracking updates at every milestone."},{"label":"Express","window":"2 – 3 Business Days","rate":"PKR 1,200","freeMsg":null,"carrier":"M&P Express","note":"Priority handling with real-time tracking. Ideal for time-sensitive orders."},{"label":"White Glove","window":"Next Day (arranged)","rate":"PKR 2,500+","freeMsg":null,"carrier":"In-house concierge team","note":"Room-of-choice delivery, professional assembly, and debris removal included."}],"faqs":[{"q":"When will my order be dispatched?","a":"Orders placed before 2 PM (PKT, Mon–Fri) are dispatched the same business day. Orders placed after 2 PM or on weekends are dispatched the next working day. You will receive a dispatch confirmation with a tracking number via SMS and email."},{"q":"Do you ship internationally?","a":"Currently, Alloyed Living ships within Pakistan only. We are expanding our logistics network and plan to offer international shipping to the UAE, UK, and USA in Q4 2026. Subscribe to our newsletter to be notified the moment it launches."},{"q":"What if my package arrives damaged?","a":"Every order is fully insured during transit. If your item arrives damaged or does not arrive within the stated window, contact us at hello@alloyedliving.com within 48 hours of the expected delivery date. We will arrange a full replacement or refund at no cost to you."},{"q":"Can I change my delivery address after placing an order?","a":"Address changes can be accommodated up to 4 hours after an order is placed, provided it has not yet been dispatched. Contact us immediately via WhatsApp or email. Once dispatched, address changes are handled directly with the courier and may incur a redirect fee."},{"q":"How can I track my order in real time?","a":"Once dispatched, you will receive an SMS with a direct tracking link from our courier partner. You can also use the order tracker at the top of this page. Tracking status is updated every 4–6 hours throughout the delivery journey."},{"q":"Are customs duties applicable?","a":"All prices on Alloyed Living are inclusive of applicable local taxes. No additional duties apply for deliveries within Pakistan. For future international orders, all applicable duties and taxes will be clearly presented at checkout before you confirm your purchase."}]}'::jsonb, '2026-07-04T05:45:24.404Z'),
  ('returns', 'Returns & Exchanges', '{"heroTitle":"Hassle-Free Returns.","heroSubtitle":"We stand behind every piece. If it doesn''t feel right, we''ll make it right.","returnWindowDays":30,"steps":[{"n":"01","label":"Request","desc":"Submit your return or exchange request online using the portal below."},{"n":"02","label":"Pack","desc":"Securely re-package the item in its original protective materials."},{"n":"03","label":"Ship","desc":"Drop off with our designated courier partner. No shipping cost to you."},{"n":"04","label":"Refund","desc":"Refund or credit processed within 5–7 business days of receipt."}],"policies":[{"id":"refund","label":"Full Refund","badge":null,"conditions":["Item in unused, original condition","All original packaging and materials intact","Requested within 14 days of delivery","Not a customised or made-to-order piece"],"note":"Refund issued to original payment method. Bank processing may take a further 3–5 business days after we complete our end."},{"id":"exchange","label":"Exchange","badge":"Most Popular","conditions":["Item in original or near-original condition","Within 30 days of delivery date","Available for a different size, finish, or item","Price difference billed or credited accordingly"],"note":"Subject to stock availability. Our concierge team will confirm the exchange within 24 hours of receiving your request."},{"id":"credit","label":"Store Credit","badge":null,"conditions":["Item returned within 45 days of delivery","Minor wear or missing secondary packaging accepted","Credit issued as a voucher code via email","Store credit never expires"],"note":"Store credit is issued at 100% of the original item value. No deductions or processing fees apply."}]}'::jsonb, '2026-05-01T10:00:00.000Z'),
  ('contact', 'Contact Us', '{"heroTitle":"Let''s Talk","heroSubtitle":"Have a question about an order, a custom piece, or just want to say hello? We are here to help.","email":"hello@alloyedliving.com","whatsapp":"https://wa.me/923001234567","hours":"Mon–Sat, 10 AM – 7 PM (PKT)"}'::jsonb, '2026-07-04T05:47:08.535Z'),
  ('about', 'About Us', '{"heroTitle":"Crafted for the Discerning Home.","body":"Alloyed Living creates ultra-luxury furniture and home decor for the modern Pakistani household. Every piece is made to order, blending heavy-gauge steel with solid hardwoods, and finished by craftsmen who have spent decades perfecting their trade. No shortcuts, no compromise."}'::jsonb, '2026-05-01T10:00:00.000Z'),
  ('faq', 'Frequently Asked Questions', '{"faqs":[{"q":"Do you offer custom sizing?","a":"Yes — most pieces can be customised in dimensions and finish. Contact our concierge team for a quote."},{"q":"How long does a made-to-order piece take?","a":"Made-to-order pieces typically take 3–5 weeks before dispatch, depending on material availability."},{"q":"Do you offer warranties?","a":"All pieces carry a 2-year structural warranty covering the steel frame and joinery."}]}'::jsonb, '2026-05-01T10:00:00.000Z'),
  ('terms', 'Terms & Conditions', '{"body":"By placing an order with Alloyed Living, you agree to our sales, shipping, and returns policies as published on this site. Prices are listed in PKR and are inclusive of applicable local taxes. Alloyed Living reserves the right to update these terms at any time."}'::jsonb, '2026-05-01T10:00:00.000Z')
insert into public.reviews (id, product_id, author, author_id, rating, comment, created_at) values
  ('rv001', 'p01', 'Ayesha Rahim', NULL, 5, 'Absolutely stunning piece. The quality is even better in person — it has completely transformed our drawing room. Every guest who visits asks about it.', '2025-03-14T10:15:00.000Z'),
  ('rv002', 'p01', 'Bilal Mahmood', NULL, 5, 'Solid construction and exceptional finishing. Delivery was on time and packed very carefully. Worth every rupee — no regrets.', '2025-02-08T16:40:00.000Z'),
  ('rv003', 'p01', 'Sana Qureshi', NULL, 4, 'Beautiful piece that everyone who visits notices and asks about. Took some time to arrive but the wait was absolutely worth it.', '2025-01-22T09:05:00.000Z'),
  ('rv004', 'p01', 'Usman Ali', NULL, 5, 'My third purchase from Alloyed Living and every piece has been perfect. Consistent craftsmanship and truly timeless design.', '2024-12-19T13:20:00.000Z'),
  ('rv005', 'p02', 'Hamza Sheikh', NULL, 5, 'The nesting tables are even more versatile than I expected. The glass and walnut combination looks premium and feels sturdy.', '2025-04-02T11:00:00.000Z'),
  ('rv006', 'p02', 'Mariam Javed', NULL, 4, 'Lovely design and great finishing. Assembly was straightforward. Only wish it came in one more colour option.', '2025-03-27T18:30:00.000Z'),
  ('rv007', 'p02', 'Muhammad Umair', '2ca93cac-9178-4ca3-97af-73dbe0dd3175', 5, 'Best product ever', '2026-07-05T04:34:50.952Z')
